 * Moves every issue from the source label onto the target, then deletes the
 * source. Runs in one transaction; returns how many issues carried the source.
 */
export async function mergeLabels(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  return getDb().transaction((tx) => {
    const issueIds = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
