          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .run();

    if (unique.length > 0) {
      tx.insert(issueLabels)
        .values(
          unique.map((issueId) => ({ orgId, issueId, labelId: targetLabelId })),
        )
        .onConflictDoNothing()
        .run();
    }

    tx.delete(labels)
      .where(
        and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)),
      )
      .run();

    return unique.length;
  });
}

